"use client";

import { cn } from "@/lib/utils";
import type { Variants } from "motion/react";
import {
 LazyMotion,
 domMin,
 m,
 useAnimation,
 useReducedMotion,
} from "motion/react";
import {
 forwardRef,
 useCallback,
 useImperativeHandle,
 useRef,
 type HTMLAttributes,
} from "react";
export interface HandshakeIconHandle {
 startAnimation: () => void;
 stopAnimation: () => void;
}

interface HandshakeIconProps extends Omit<
 HTMLAttributes<HTMLDivElement>,
 | "color"
 | "onDrag"
 | "onDragStart"
 | "onDragEnd"
 | "onAnimationStart"
 | "onAnimationEnd"
 | "onAnimationIteration"
> {
 size?: number;
 duration?: number;
 isAnimated?: boolean;
 color?: string;
}

const HandshakeIcon = forwardRef<HandshakeIconHandle, HandshakeIconProps>(
 (
  {
   onMouseEnter,
   onMouseLeave,
   className,
   size = 24,
   duration = 1,
   isAnimated = true,
   color,
   ...props
  },
  ref,
 ) => {
  const controls = useAnimation();
  const reduced = useReducedMotion();
  const isControlled = useRef(false);

  useImperativeHandle(ref, () => {
   isControlled.current = true;
   return {
    startAnimation: () =>
     reduced ? controls.start("normal") : controls.start("animate"),
    stopAnimation: () => controls.start("normal"),
   };
  });

  const handleEnter = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isAnimated || reduced) return;
    if (!isControlled.current) controls.start("animate");
    else onMouseEnter?.(e as any);
   },
   [controls, reduced, isAnimated, onMouseEnter],
  );

  const handleLeave = useCallback(
   (e?: React.MouseEvent<HTMLDivElement>) => {
    if (!isControlled.current) controls.start("normal");
    else onMouseLeave?.(e as any);
   },
   [controls, onMouseLeave],
  );

  const shakeVariants: Variants = {
   normal: { y: 0 },
   animate: {
    y: [0, 1.5, -1.5, 1, -0.5, 0],
    transition: { duration: 0.6 * duration, ease: "easeInOut" },
   },
  };

  return (
   <LazyMotion features={domMin} strict>
    <m.div
     className={cn("inline-flex items-center justify-center", className)}
     onMouseEnter={handleEnter}
     onMouseLeave={handleLeave}
     {...props}
     style={{ color, ...props.style }}
    >
     <m.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      animate={controls}
      initial="normal"
     >
      <m.g variants={shakeVariants}>
       <path d="M14.5 8.49951C13.6329 8.93304 11.1118 9.66731 8.63166 9.5941C7.98001 9.57486 7.5 9.01526 7.5 8.36333C7.5 7.83928 7.81029 7.36341 8.28079 7.13264C9.28416 6.64049 10.867 5.81798 12.2709 5.05868C13.1233 4.5977 13.5495 4.3672 13.8726 4.25809C14.7383 3.96573 15.4351 3.95453 16.3097 4.21893C16.6362 4.3176 17.0283 4.51365 17.8124 4.90573L18.7167 5.35787C18.7884 5.39372 18.8243 5.41165 18.861 5.42651C18.9555 5.46475 19.0553 5.48831 19.1569 5.49637C19.1964 5.49951 19.2365 5.49951 19.3167 5.49951C19.9522 5.49951 20.2699 5.49951 20.5302 5.57107C21.2102 5.75804 21.7415 6.28929 21.9284 6.96928C22 7.22956 22 7.5473 22 8.18279V13.7138C22 14.4239 21.4244 14.9995 20.7143 14.9995C20.5752 14.9995 20.4398 15.0446 20.3286 15.1281L20 15.3745C19.3066 15.8945 18.9599 16.1546 18.5624 16.3051C18.4871 16.3336 18.4108 16.359 18.3335 16.3814C17.9251 16.4995 17.4917 16.4995 16.625 16.4995H14" />
       <path d="M14.5 8.49902L17.5713 11.9775C18.0912 12.5494 18.0703 13.4287 17.5238 13.9752C16.9584 14.5407 16.0416 14.5407 15.4762 13.9752C16.0285 14.5275 16.0523 15.4467 15.5 15.999C14.9477 16.5513 14.0523 16.5513 13.5 15.999L13 15.499C13.5523 16.0513 13.5523 16.9467 13 17.499C12.4477 18.0513 11.5523 18.0513 11 17.499C11.5523 18.0513 11.5523 18.9467 11 19.499L10.9393 19.5597C10.658 19.841 10.2765 19.999 9.87868 19.999H9.75C9.26978 19.999 8.80923 19.8083 8.46967 19.4687L4.41421 15.4132C4.149 15.148 3.78929 14.999 3.41421 14.999C2.63317 14.999 2 14.3659 2 13.5848L2 9.49902C2 7.61341 2 6.6706 2.58579 6.08481C3.17157 5.49902 4.11438 5.49902 6 5.49902L11 5.49902" />
      </m.g>
     </m.svg>
    </m.div>
   </LazyMotion>
  );
 },
);

HandshakeIcon.displayName = "HandshakeIcon";
export { HandshakeIcon };
